function renderSceneControlBoard(){
  const root=$('#sceneControlRows');if(!root)return;renderSceneTimeSeriesTabs();
  const nodes=state.graph.nodes||[];
  if(!nodes.length){root.innerHTML='<div class="scene-board-empty">从右侧模型库拖拽渲染缩略图到上方场景，即可加入联合仿真。</div>';return}
  const entries=[];let maxEnd=1;
  for(const node of nodes){
    const model=graphModelSummary(node.model_id),library=state.timeSeriesCache.get(node.model_id),series=selectedSceneTimeSeries(node.model_id,library);
    if(!state.timeSeriesCache.has(node.model_id)&&!state.timeSeriesLoading.has(node.model_id))void ensureTimeSeries(node.model_id).then(()=>renderSceneControlBoard());
    const drives=(series?.drives||[]).filter(drive=>drive&&drive.enabled!==false);
    const segments=drives.flatMap(drive=>(drive.segments||[]).filter(segment=>Number(segment.end)>Number(segment.start)));
    const earliest=segments.length?Math.min(...segments.map(segment=>Math.max(0,Number(segment.start)||0))):0;
    const latest=segments.length?Math.max(...segments.map(segment=>Math.max(0,Number(segment.end)||0))):0;
    maxEnd=Math.max(maxEnd,latest);
    entries.push({node,model,series,drives,segments,earliest,latest});
  }
  const axisEnd=Math.max(1,Math.ceil(maxEnd)),ticks=Array.from({length:axisEnd+1},(_,index)=>`<span style="left:${index/axisEnd*100}%"><i></i><b>${index}s</b></span>`).join('');
  const rows=entries.map(({node,model,series,drives,segments,earliest,latest})=>{
    const left=Math.min(100,earliest/axisEnd*100),width=segments.length?Math.max(1.2,Math.min(100-left,(latest-earliest)/axisEnd*100)):0;
    const block=segments.length?`<span class="scene-time-drive-span" style="left:${left}%;width:${width}%" title="${esc(model.name)} · 全部驱动 ${formatNumber(earliest,3)}–${formatNumber(latest,3)} s · ${segments.length} 个运动段"><i>${formatNumber(earliest,2)}–${formatNumber(latest,2)}s</i></span>`:'';
    const subtitle=series?`${drives.length} 驱动 · ${segments.length} 段 · ${esc(series.name||'当前时序')}`:'尚无时序表';
    return `<div class="scene-control-row ${state.graphSelection.has(node.id)?'active':''}" data-scene-node="${node.id}" data-scene-select-model="${esc(node.model_id)}"><div class="scene-control-name"><strong>${esc(model.name)}</strong><small>${subtitle}</small></div><div class="scene-time-lane" title="该模型全部驱动最早开始至最晚结束">${block}</div><button type="button" data-scene-edit-time-series="${esc(node.model_id)}">编辑</button></div>`;
  }).join('');
  root.innerHTML=`<div class="scene-time-axis-row"><div class="scene-axis-label">名称</div><div class="scene-time-axis-track">${ticks}</div><div class="scene-axis-edit-label">操作</div></div>${rows}`;
}

