function tableHeaderKey(value){return String(value??'').trim().toLowerCase().replace(/[\s_\-./\\|()[\]{}:：·，,]+/g,'').replace(/(?:position|angle|displacement|degree|degrees|deg|位置|角度|位移|°|mm)$/i,'')}
function driveHeaderAliases(d){const part=activityPart(d.activity_part_id),motion=part?.motions?.find(m=>m.id===d.motion_id),base=[d.id,d.name,d.joint_id,d.motion_id,motion?.name,part?.name,part&&motion?`${part.name}${motion.name}`:''];return[...new Set(base.map(tableHeaderKey).filter(Boolean))]}
function buildExternalTable(matrix,fileName=''){if(!state.model)throw new Error('请先选择模型');if(!Array.isArray(matrix)||matrix.length<2)throw new Error('CSV 至少需要 1 行表头和 1 行数据');const headers=matrix[0].map(x=>String(x??'').trim());if(headers.length<2)throw new Error('CSV 至少需要两列：第一列时间，第二列起为电机位置');const choices=(state.model.drives||[]).filter(d=>d.enabled!==false),mapping=[],unmatched=[],used=new Set();for(let column=1;column<headers.length;column++){const header=headers[column];if(!header){unmatched.push(`第 ${column+1} 列（空表头）`);continue}const key=tableHeaderKey(header),matches=choices.filter(d=>driveHeaderAliases(d).includes(key));if(matches.length>1)throw new Error(`表头“${header}”匹配到多个电机，请改用更完整的动作名称或驱动 ID`);if(matches.length===0){unmatched.push(header);continue}const d=matches[0];if(used.has(d.id))throw new Error(`多个表头重复匹配到电机“${d.name}”`);used.add(d.id);mapping.push({column,header,drive_id:d.id,drive_name:d.name})}if(!mapping.length)throw new Error('第二列起没有表头能匹配当前模型的电机；可使用动作名称、驱动名称或驱动 ID 作为表头');const rows=[];let previousTime=-1,valueCount=0;for(let index=1;index<matrix.length;index++){const cells=matrix[index],rawTime=String(cells[0]??'').trim(),time=Number(rawTime);if(rawTime===''||!Number.isFinite(time))throw new Error(`CSV 第 ${index+1} 行时间无效`);if(time<0)throw new Error(`CSV 第 ${index+1} 行时间不能小于 0`);if(time<=previousTime)throw new Error(`CSV 第 ${index+1} 行时间必须大于上一行`);previousTime=time;const positions={};for(const item of mapping){const raw=String(cells[item.column]??'').trim();if(raw==='')continue;const value=Number(raw),d=drive(item.drive_id);if(!Number.isFinite(value))throw new Error(`CSV 第 ${index+1} 行“${item.header}”不是有效数字`);if(value<Number(d.reverse_limit)-1e-9||value>Number(d.forward_limit)+1e-9)throw new Error(`CSV 第 ${index+1} 行“${item.header}”超出 ${formatNumber(d.reverse_limit)} ~ ${formatNumber(d.forward_limit)}`);positions[item.drive_id]=value;valueCount++}rows.push({time,positions})}if(!valueCount)throw new Error('CSV 没有可执行的电机位置数据');return{name:fileName||'外部表格.csv',headers,mapping,unmatched,previewRows:matrix.slice(1,Math.min(matrix.length,7)),sequence:{source_name:fileName||'',rows},rowCount:rows.length,duration:rows.length?rows[rows.length-1].time:0}}
async function readCsvFile(file){const buffer=await file.arrayBuffer();try{return new TextDecoder('utf-8',{fatal:true}).decode(buffer)}catch(_){try{return new TextDecoder('gb18030').decode(buffer)}catch(__){throw new Error('CSV 编码无法识别，请保存为 UTF-8 CSV 后重试')}}}
function manualModeToggleHtml(compact=false){return `<label class="control-source-switch ${compact?'compact':''}" title="关闭：使用外部表格；开启：使用手动输入"><span>表格</span><input data-manual-mode type="checkbox" ${state.manualMode?'checked':''} aria-label="表格-手动控制切换"><span class="control-source-track" aria-hidden="true"></span><b>手动</b></label>`}
function bindManualModeToggles(root=document){root.querySelectorAll('[data-manual-mode]').forEach(input=>input.onchange=()=>setManualMode(input.checked))}
function setManualMode(manual){manual=!!manual;if(!manual&&!state.externalTable){toast('请先在“外部表格”中导入 CSV','error');state.manualMode=true;renderSteps();if(state.upper==='external')renderUpper();return false}state.manualMode=manual;renderSteps();if(state.upper==='external')renderUpper();updateActionButtons();toast(manual?'已切换为手动输入':'已切换为外部表格控制','success');return true}
async function importExternalCsvFile(file){if(!file)return;const text=await readCsvFile(file),table=buildExternalTable(parseCsv(text),file.name);state.externalTable=table;renderUpper();renderSteps();updateActionButtons();toast(`已导入 ${table.rowCount} 行表格数据，匹配 ${table.mapping.length} 个电机`,'success')}
function renderExternalTablePanel(root){const table=state.externalTable;if(!table){root.innerHTML=`<div class="external-table-panel"><input id="externalCsvInput" class="hidden" type="file" accept=".csv,text/csv"><div class="external-table-empty"><strong>导入 CSV 控制顺序</strong><span>自动识别首行表头：第一列为时间（秒），第二列起按表头匹配各电机的位置角度/位移。</span><button class="secondary" data-import-csv>选择 CSV 文件</button></div></div>`}else{const warning=table.unmatched.length?`<div class="external-table-warning">未匹配列：${table.unmatched.map(esc).join('、')}（这些列不会参与仿真）</div>`:'';root.innerHTML=`<div class="external-table-panel"><input id="externalCsvInput" class="hidden" type="file" accept=".csv,text/csv"><div class="external-table-summary"><div><strong>${esc(table.name)}</strong><span>${table.rowCount} 行 · ${table.mapping.length} 个电机 · ${formatNumber(table.duration)} s</span></div>${manualModeToggleHtml(false)}<button class="secondary" data-import-csv>重新导入</button><button class="ghost" data-clear-csv>清除</button></div><div class="external-table-mapping">${table.mapping.map(item=>`<span>${esc(item.header)} → ${esc(item.drive_name)}</span>`).join('')}</div>${warning}<div class="external-table-preview"><table><thead><tr>${table.headers.map(h=>`<th>${esc(h||'（空）')}</th>`).join('')}</tr></thead><tbody>${table.previewRows.map(row=>`<tr>${table.headers.map((_,i)=>`<td>${esc(row[i]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}const input=root.querySelector('#externalCsvInput'),button=root.querySelector('[data-import-csv]');if(button&&input){button.onclick=()=>input.click();input.onchange=async()=>{try{await importExternalCsvFile(input.files?.[0])}catch(error){toast(error.message,'error')}finally{input.value=''}}}const clear=root.querySelector('[data-clear-csv]');if(clear)clear.onclick=()=>{state.externalTable=null;if(!state.manualMode)state.manualMode=true;renderUpper();renderSteps();updateActionButtons();toast('外部表格已清除')};bindManualModeToggles(root)}
function drive(id){return state.model?.drives.find(x=>x.id===id)}
function memory(id){return state.model?.memories.find(x=>x.id===id)}
function activityPart(id){return state.model?.activity_parts?.find(x=>x.id===id)}
function drivesForPart(partId){return (state.model?.drives||[]).filter(d=>d.activity_part_id===partId&&d.enabled!==false)}
function partIdForDrive(driveId){return drive(driveId)?.activity_part_id||''}
function calibration(d){const p0=Number(d.position_0_percent??d.initial_position??(d.zero_at==='reverse'?d.reverse_limit:d.forward_limit));const action=(d.actions||[]).find(x=>Number.isFinite(Number(x.target)));const p100=Number(d.position_100_percent??action?.target??(d.zero_at==='reverse'?d.forward_limit:d.reverse_limit));return[p0,p100]}
function percent(d,value){const[p0,p100]=calibration(d),span=p100-p0;return span?Math.max(0,Math.min(100,(Number(value)-p0)/span*100)):0}
function rawPositionPercent(d,value){const[p0,p100]=calibration(d),span=p100-p0;return span?(Number(value)-p0)/span*100:0}
function positionFromPercent(d,value){const[p0,p100]=calibration(d),pct=Math.max(0,Math.min(100,finite(value,0)));return clampDriveValue(d,p0+(p100-p0)*pct/100)}
function clampDriveValue(d,value){return Math.max(Number(d.reverse_limit),Math.min(Number(d.forward_limit),Number(value)))}
function currentDriveValue(d){if(!d)return 0;const v=Number(state.currentPositions[d.id]);if(Number.isFinite(v))return clampDriveValue(d,v);return clampDriveValue(d,finite(d.initial_position,calibration(d)[0]))}
function actionTarget(d,actionId=''){const action=(d?.actions||[]).find(x=>x.id===actionId)||(d?.actions||[])[0];return Number.isFinite(Number(action?.target))?Number(action.target):calibration(d||{})[1]}
function defaultStep(){return{id:uid('step'),part_id:'',drive_id:'',action_id:'',start:{mode:'current',memory_id:'',value:0},end:{mode:'value',memory_id:'',value:0,source:'position',input_value:0}}}
function resolveLegacyStart(raw,d){const spec={mode:'current',memory_id:'',value:0,...clone(raw||{})};if(spec.mode==='memory'){const m=memory(spec.memory_id),v=d&&m?.positions?.[d.id];return{mode:'value',memory_id:'',value:Number.isFinite(Number(v))?Number(v):currentDriveValue(d)}}if(spec.mode!=='value')return{mode:'current',memory_id:'',value:currentDriveValue(d)};return{mode:'value',memory_id:'',value:finite(spec.value,currentDriveValue(d))}}
function resolveLegacyEnd(raw,d,actionId){const spec={mode:'value',memory_id:'',value:actionTarget(d,actionId),...clone(raw||{})};let value=Number(spec.value);if(spec.mode==='memory'){const m=memory(spec.memory_id);value=Number(m?.positions?.[d?.id])}else if(spec.mode==='action')value=actionTarget(d,actionId);if(!Number.isFinite(value))value=actionTarget(d,actionId);const source=['travel','travel_percent','position','position_percent'].includes(spec.source)?spec.source:'position';const inputValue=Number.isFinite(Number(spec.input_value))?Number(spec.input_value):value;return{mode:'value',memory_id:'',value,source,input_value:inputValue}}
function normalizeStep(raw={}){const d=drive(raw.drive_id);const s=defaultStep();s.drive_id=d?.id||'';s.part_id=raw.part_id||d?.activity_part_id||'';s.action_id=d?((d.actions||[]).some(x=>x.id===raw.action_id)?raw.action_id:(d.actions||[])[0]?.id||''):'';s.start=resolveLegacyStart(raw.start,d);s.end=resolveLegacyEnd(raw.end,d,s.action_id);if(d)syncEndForStep(s);return s}
function endValueFromSource(step,d,start){const source=['travel','travel_percent','position','position_percent'].includes(step.end?.source)?step.end.source:'position',inputValue=finite(step.end?.input_value,finite(step.end?.value,actionTarget(d,step.action_id))),[p0,p100]=calibration(d),span=p100-p0||1;if(source==='travel')return start+inputValue;if(source==='travel_percent')return start+inputValue/100*span;if(source==='position_percent')return p0+inputValue/100*span;return inputValue}
function projectedDriveValueBefore(index,d){let current=currentDriveValue(d);for(let n=0;n<index;n++){const previous=state.steps[n];if(previous?.drive_id!==d.id)continue;const start=previous.start?.mode==='value'?clampDriveValue(d,finite(previous.start.value,current)):current;current=endValueFromSource(previous,d,start)}return current}
function stepStartValue(step,d,index=null){if(!d)return 0;if(step.start?.mode==='value')return clampDriveValue(d,finite(step.start.value,currentDriveValue(d)));const resolvedIndex=Number.isInteger(index)?index:state.steps.indexOf(step);return resolvedIndex>=0?projectedDriveValueBefore(resolvedIndex,d):currentDriveValue(d)}
function endMetrics(step,d,index=null){if(!d)return{travel:0,travel_percent:0,position:0,position_percent:0};const start=stepStartValue(step,d,index),end=finite(step.end?.value,actionTarget(d,step.action_id)),[p0,p100]=calibration(d),span=p100-p0;return{travel:end-start,travel_percent:span?(end-start)/span*100:0,position:end,position_percent:span?(end-p0)/span*100:0}}
function syncEndForStep(step,index=null){const d=drive(step.drive_id);if(!d)return;step.end=step.end||{mode:'value',value:actionTarget(d,step.action_id),source:'position',input_value:actionTarget(d,step.action_id)};const source=['travel','travel_percent','position','position_percent'].includes(step.end.source)?step.end.source:'position';const inputValue=finite(step.end.input_value,finite(step.end.value,actionTarget(d,step.action_id))),start=stepStartValue(step,d,index);step.end.mode='value';step.end.source=source;step.end.input_value=inputValue;step.end.value=Number(endValueFromSource(step,d,start))}
function serializeStep(step,index=null){const d=drive(step.drive_id);if(d)syncEndForStep(step,index);return{drive_id:step.drive_id,action_id:step.action_id,start:step.start?.mode==='value'?{mode:'value',value:finite(step.start.value,currentDriveValue(d))}:{mode:'current'},end:{mode:'value',value:finite(step.end?.value,0),source:step.end?.source||'position',input_value:finite(step.end?.input_value,finite(step.end?.value,0))}}}
async function loadClientSettings(){try{return await api('/api/user-settings')}catch(error){console.warn('读取用户设置失败',error);return{render_quality:'preview'}}}
function applyRenderQualityUi(){const perfect=state.renderQuality==='perfect';$('#renderQualityToggle').checked=perfect;$('#renderModeLabel').textContent=perfect?'高质量渲染':'快速渲染'}
async function saveClientSettings(){const button=$('#saveUserSettings');button.disabled=true;try{await api('/api/user-settings',{method:'POST',body:JSON.stringify({render_quality:state.renderQuality})});toast('渲染设置已保存','success')}catch(error){toast(error.message,'error')}finally{button.disabled=false}}
async function loadModels(){const[data,prefs,library,graph]=await Promise.all([api('/api/models?scope=client'),loadClientSettings(),api('/api/model-library'),api('/api/control-graph')]);state.models=data.models;state.library=library;state.graph=graph;state.renderQuality=prefs.render_quality==='perfect'?'perfect':'preview';applyRenderQualityUi();$('#modelSelect').innerHTML=data.models.map(m=>`<option value="${m.id}">${esc(m.name)}${m.source_name?`（原：${esc(m.source_name)}）`:''}</option>`).join('');renderClientLibrary();renderGraph();renderSceneControlBoard();const first=(state.graph.nodes||[]).find(node=>state.models.some(m=>m.id===node.model_id))?.model_id||data.models[0]?.id;if(first)await selectModel(first,{loadAnimation:false});else renderAll();if((state.graph.nodes||[]).length)await loadSceneAnimation({autoplay:false});else clearSceneAnimation()}
function animationUrl(base,{modelId,camera,autoplay=false,view='front'}={}){const params=new URLSearchParams();params.set('model_id',modelId||'');params.set('autoplay',autoplay?'1':'0');params.set('view',view||'front');if(camera)params.set('camera',JSON.stringify(camera));return `${base}${base.includes('?')?'&':'?'}${params.toString()}`}
async function loadAnimation({modelId,steps=[],autoplay=false,camera=null,token=state.loadToken,memoryJumpId='',targetPositions=null,tableSequence=null,initialPositions=null}={}){const suppliedPositions={...(initialPositions||state.currentPositions)};const payload={model_id:modelId,steps:steps.map((step,index)=>serializeStep(step,index)),render_quality:state.renderQuality,initial_positions:suppliedPositions};if(memoryJumpId)payload.memory_jump_id=memoryJumpId;if(targetPositions!==null)payload.target_positions={...targetPositions};if(tableSequence!==null)payload.table_sequence=clone(tableSequence);let data;try{data=await api('/api/simulate',{method:'POST',body:JSON.stringify(payload)})}catch(error){if(token!==state.loadToken||state.model?.id!==modelId)return false;throw error}if(token!==state.loadToken||state.model?.id!==modelId)return false;state.currentPositions={...(data.final_positions||{})};refreshCurrentStepValues();const iframe=$('#animationFrame');state.frameModelId=modelId;iframe.src=animationUrl(data.url,{modelId,camera,autoplay,view:'front'});$('#clientEmpty').classList.add('hidden');return true}
async function selectModel(id,{loadAnimation:shouldLoadAnimation=true}={}){const token=++state.loadToken;const data=await api(`/api/models/${id}`);if(token!==state.loadToken)return;state.model=data.model;state.modelCache.set(id,state.model);state.model.drives.forEach(d=>{d.actions=d.actions||(d.segments||[]).map(s=>({id:s.id,name:s.name,target:Number(d.initial_position||0)+Number(s.travel||0)}))});$('#modelSelect').value=id;state.steps=[];state.currentPositions={};state.undoHistory=[];state.camera=null;state.manualMode=true;state.externalTable=null;cancelPoseActions();renderAll();if(!shouldLoadAnimation){renderSceneControlBoard();return}$('#clientEmpty').classList.remove('hidden');$('#clientEmpty').innerHTML='<div><div class="brand-mark" style="margin:0 auto 14px">3D</div><strong>正在生成静止动画…</strong><p>每次进入或切换模型均从正视图开始</p></div>';try{await loadAnimation({modelId:id,steps:[],autoplay:false,camera:null,token,initialPositions:{}})}catch(error){if(token===state.loadToken){$('#clientEmpty').classList.remove('hidden');$('#clientEmpty').innerHTML=`<div><strong>动画加载失败</strong><p>${esc(error.message)}</p></div>`;toast(error.message,'error')}}}
function currentPoseSnapshot(){if(!state.model)return null;const positions={};for(const d of state.model.drives||[])positions[d.id]=currentDriveValue(d);return{model_id:state.model.id,positions}}
function updateUndoButton(){const button=$('#undoPosition');if(!button)return;const count=state.undoHistory.length;button.disabled=state.poseBusy||!state.model||count===0;button.title=count?`回退到上一步初始位置（可撤销 ${count} 步，最多 3 步）`:'暂无可撤销的位置'}
function updateActionButtons(){const hasModel=!!state.model,hasDrives=!!state.model?.drives?.length,hasSteps=state.steps.length>0,manual=state.manualMode,hasTable=!!state.externalTable;const add=$('#addStep'),save=$('#saveSteps'),clear=$('#clearSteps'),simulate=$('#simulate');if(add)add.disabled=!hasDrives||!manual;if(save)save.disabled=!hasModel||!hasSteps||!manual;if(clear)clear.disabled=!hasModel||!hasSteps||!manual;if(simulate)simulate.disabled=state.poseBusy||!hasModel||(!manual&&!hasTable);$$('[data-jump-memory]').forEach(button=>{button.disabled=state.poseBusy})}
function beginPoseAction(){const actionToken=++state.poseActionToken;state.poseBusy=true;updateUndoButton();updateActionButtons();return actionToken}
function endPoseAction(actionToken){if(actionToken!==state.poseActionToken)return;state.poseBusy=false;updateUndoButton();updateActionButtons()}
function cancelPoseActions(){state.poseActionToken+=1;state.poseBusy=false;updateUndoButton();updateActionButtons()}
function pushUndoSnapshot(){const snapshot=currentPoseSnapshot();if(!snapshot)return null;state.undoHistory.push(snapshot);if(state.undoHistory.length>UNDO_POSITION_LIMIT)state.undoHistory.splice(0,state.undoHistory.length-UNDO_POSITION_LIMIT);updateUndoButton();return snapshot}
function discardUndoSnapshot(snapshot){const index=state.undoHistory.lastIndexOf(snapshot);if(index>=0)state.undoHistory.splice(index,1);updateUndoButton()}
function restoreUndoSnapshot(snapshot){if(!snapshot||snapshot.model_id!==state.model?.id)return;state.undoHistory.push(snapshot);if(state.undoHistory.length>UNDO_POSITION_LIMIT)state.undoHistory.splice(0,state.undoHistory.length-UNDO_POSITION_LIMIT);updateUndoButton()}
async function undoLastPosition(){if(!state.model||!state.undoHistory.length||state.poseBusy)return;const target=state.undoHistory.pop(),current=currentPoseSnapshot(),actionToken=beginPoseAction();try{const modelId=state.model.id,token=++state.loadToken,applied=await loadAnimation({modelId,autoplay:true,camera:state.camera,token,targetPositions:target.positions,initialPositions:current?.positions||{}});if(!applied){restoreUndoSnapshot(target);return}toast(`已回退到上一步初始位置${state.undoHistory.length?`，还可撤销 ${state.undoHistory.length} 步`:''}`,'success')}catch(error){restoreUndoSnapshot(target);toast(error.message,'error')}finally{endPoseAction(actionToken)}}
function renderUpper(){const root=$('#upperContent'),add=$('#addMemory');if(add)add.classList.toggle('hidden',state.upper!=='memories'||!state.model);if(!state.model){root.innerHTML='<div class="empty-state">暂无可用模型</div>';return}if(state.upper==='presets'){root.innerHTML=state.model.presets.map(p=>`<button class="preset-btn" data-preset="${p.id}" title="双击载入"><strong>${esc(p.name)}</strong><span>${p.steps.length} 个步骤 · 双击载入</span></button>`).join('')||'<div class="empty-state">暂无预设控制逻辑</div>';$$('[data-preset]').forEach(e=>e.ondblclick=()=>{const p=state.model.presets.find(x=>x.id===e.dataset.preset);state.steps=(p.steps||[]).map(normalizeStep);state.steps.forEach((step,index)=>syncEndForStep(step,index));if(!state.manualMode)state.manualMode=true;renderSteps();toast(`已载入“${p.name}”`)})}else if(state.upper==='memories'){const driveCount=state.model.drives.length;root.innerHTML=state.model.memories.map(m=>`<div class="memory-card memory-card-collapsed" data-edit-memory="${m.id}" tabindex="0" title="双击编辑“${esc(m.name)}”的各驱动百分比"><div class="memory-summary"><div class="memory-summary-name"><strong>${esc(m.name)}</strong><span>${driveCount} 个驱动 · 数据已折叠 · 双击编辑</span></div><button class="secondary memory-jump" data-jump-memory="${m.id}" title="跳转到该记忆位置">跳转</button><button class="danger icon-btn memory-delete" data-del-memory="${m.id}" title="删除记忆位置">×</button></div></div>`).join('')||'<div class="empty-state">暂无记忆位置</div>';$$('[data-edit-memory]').forEach(e=>{e.ondblclick=event=>{if(event.target.closest('button'))return;showMemoryEditor(e.dataset.editMemory)};e.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();showMemoryEditor(e.dataset.editMemory)}}});$$('[data-jump-memory]').forEach(e=>{e.onclick=event=>{event.stopPropagation();jumpToMemory(e.dataset.jumpMemory,e)};e.ondblclick=event=>event.stopPropagation()});$$('[data-del-memory]').forEach(e=>{e.onclick=event=>{event.stopPropagation();deleteMemory(e.dataset.delMemory)};e.ondblclick=event=>event.stopPropagation()})}else renderExternalTablePanel(root)}
function driveOptions(step){const choices=(state.model?.drives||[]).filter(d=>d.enabled!==false);return `<option value="">选择动作</option>${choices.map(d=>{const part=activityPart(d.activity_part_id),motion=part?.motions?.find(m=>m.id===d.motion_id);return `<option value="${d.id}" ${d.id===step.drive_id?'selected':''}>${esc(motion?.name||d.name)}</option>`}).join('')}`}
function metricField(i,source,label,value,active,disabled=false){return `<label class="metric-field ${active?'is-active':'is-derived'} ${disabled?'is-disabled':''}"><span>${label}</span><input data-end-source="${i}:${source}" type="number" step="any" value="${formatNumber(value)}" ${active&&!disabled?'':'readonly'} ${disabled?'disabled':''} aria-label="${label}"></label>`}
function renderStep(step,i){const d=drive(step.drive_id),metrics=endMetrics(step,d,i),source=step.end?.source||'position',startValue=stepStartValue(step,d),startPct=d?rawPositionPercent(d,startValue):0,manual=state.manualMode,disabled=!d||!manual;return `<div class="step-card compact-step-card ${manual?'':'is-table-mode'}" data-step-card="${i}"><div class="step-compact-grid"><button type="button" class="step-drag-handle" data-drag-step="${i}" draggable="${manual?'true':'false'}" title="拖拽调整步骤顺序" aria-label="拖拽步骤 ${i+1}" ${manual?'':'disabled'}>⠿</button><section class="step-column-group step-sequence-group" aria-label="序号"><div class="step-group-title">序号</div><div class="step-sequence-value"><strong>${i+1}</strong><button type="button" data-del-step="${i}" class="step-delete" title="删除步骤" aria-label="删除步骤 ${i+1}" ${manual?'':'disabled'}>×</button></div></section><section class="step-column-group step-object-group" aria-label="动作"><div class="step-group-title">动作</div><select class="compact-step-select ${manual?'':'is-locked'}" data-drive="${i}" aria-label="步骤 ${i+1} 动作" ${manual?'':'disabled'}>${driveOptions(step)}</select>${manualModeToggleHtml(true)}</section><section class="step-column-group step-start-group" aria-label="起始位置"><div class="step-group-title">起始位置</div><label class="current-toggle"><input data-start-current="${i}" type="checkbox" ${step.start?.mode!=='value'?'checked':''} ${disabled?'disabled':''}><span class="toggle-track"></span><b>当前位置</b></label><label class="start-value-field ${step.start?.mode==='value'&&manual?'is-active':'is-derived'}"><span>数值</span><input data-start-value="${i}" type="number" step="any" value="${formatNumber(startValue)}" ${step.start?.mode==='value'&&d&&manual?'':'readonly'} ${disabled?'disabled':''}><i data-start-percent="${i}">${d?`${formatNumber(startPct,1)}%`:'—'}</i></label></section><section class="step-column-group step-end-group" aria-label="结束位置"><div class="step-group-title">结束位置</div><div class="end-metric-row">${metricField(i,'travel','行程',metrics.travel,source==='travel'&&manual,disabled)}${metricField(i,'position','位置',metrics.position,source==='position'&&manual,disabled)}</div><div class="end-metric-row">${metricField(i,'travel_percent','百分比',metrics.travel_percent,source==='travel_percent'&&manual,disabled)}${metricField(i,'position_percent','百分比',metrics.position_percent,source==='position_percent'&&manual,disabled)}</div></section></div></div>`}
function renderSteps(){const root=$('#steps');if(!state.model){root.innerHTML='<div class="empty-state">暂无模型</div>';updateActionButtons();return}const empty=state.manualMode?'<div class="empty-state compact-empty">暂无控制步骤；右侧仍显示当前静止动画</div>':`<div class="table-mode-banner"><div><strong>外部表格控制已启用</strong><span>${state.externalTable?`${esc(state.externalTable.name)} · ${state.externalTable.rowCount} 行 · ${formatNumber(state.externalTable.duration)} s`:'尚未导入 CSV'}</span></div>${manualModeToggleHtml(true)}</div>`;root.innerHTML=state.steps.map(renderStep).join('')||empty;bindSteps();updateActionButtons()}
function renderAll(){renderUpper();renderSteps();renderGraph();renderSceneControlBoard();renderSceneCoordinateBadge();updateUndoButton();updateActionButtons()}
function updateEndInputs(i){const step=state.steps[i],d=drive(step?.drive_id);if(!step||!d)return;syncEndForStep(step,i);const metrics=endMetrics(step,d,i);for(const source of ['travel','position','travel_percent','position_percent']){const input=$(`[data-end-source="${i}:${source}"]`);if(!input)continue;const value=metrics[source];if(document.activeElement!==input)input.value=formatNumber(value);const field=input.closest('.metric-field'),active=step.end.source===source;field?.classList.toggle('is-active',active);field?.classList.toggle('is-derived',!active);input.readOnly=!active}}
function refreshCurrentStepValues(){state.steps.forEach((step,i)=>{const d=drive(step.drive_id);if(!d)return;if(step.start?.mode!=='value'){step.start.value=stepStartValue(step,d,i);const input=$(`[data-start-value="${i}"]`),pct=$(`[data-start-percent="${i}"]`);if(input&&document.activeElement!==input)input.value=formatNumber(step.start.value);if(pct)pct.textContent=`${formatNumber(rawPositionPercent(d,step.start.value),1)}%`}syncEndForStep(step,i);updateEndInputs(i)})}
function activateStartValue(i,input){const step=state.steps[i],d=drive(step?.drive_id);if(!step||!d||step.start?.mode==='value')return;const projected=stepStartValue(step,d,i);step.start.mode='value';step.start.value=projected;input.readOnly=false;input.value=formatNumber(step.start.value);const field=input.closest('.start-value-field');field?.classList.remove('is-derived');field?.classList.add('is-active');const toggle=$(`[data-start-current="${i}"]`);if(toggle)toggle.checked=false;syncEndForStep(step,i);refreshCurrentStepValues()}
function activateEndSource(i,source,input){const step=state.steps[i],d=drive(step?.drive_id);if(!step||!d||step.end?.source===source)return;const metrics=endMetrics(step,d,i);step.end.source=source;step.end.input_value=metrics[source];input.readOnly=false;input.value=formatNumber(metrics[source]);updateEndInputs(i)}
function bindSteps(){bindManualModeToggles($('#steps'));$$('[data-drive]').forEach(e=>e.onchange=()=>{const i=+e.dataset.drive,s=state.steps[i],d=drive(e.value);s.drive_id=e.value;s.part_id=d?.activity_part_id||s.part_id;s.action_id=d?.actions?.[0]?.id||'';const current=currentDriveValue(d);s.start={mode:'current',memory_id:'',value:current};const target=actionTarget(d,s.action_id);s.end={mode:'value',memory_id:'',value:target,source:'position',input_value:target};renderSteps()});$$('[data-start-current]').forEach(e=>e.onchange=()=>{const i=+e.dataset.startCurrent,s=state.steps[i],d=drive(s.drive_id);if(!d)return;const projected=stepStartValue(s,d,i);s.start.mode=e.checked?'current':'value';s.start.value=projected;syncEndForStep(s,i);renderSteps()});$$('[data-start-value]').forEach(e=>{const i=+e.dataset.startValue;e.onpointerdown=()=>activateStartValue(i,e);e.onfocus=()=>activateStartValue(i,e);e.oninput=()=>{const s=state.steps[i],d=drive(s.drive_id),v=Number(e.value);if(!d||!Number.isFinite(v))return;s.start.mode='value';s.start.value=v;const pct=$(`[data-start-percent="${i}"]`);if(pct)pct.textContent=`${formatNumber(rawPositionPercent(d,v),1)}%`;syncEndForStep(s,i);refreshCurrentStepValues()};e.onchange=()=>{const s=state.steps[i],d=drive(s.drive_id),v=Number(e.value);if(!d||!Number.isFinite(v))return;s.start.value=clampDriveValue(d,v);e.value=formatNumber(s.start.value);syncEndForStep(s,i);refreshCurrentStepValues()}});$$('[data-end-source]').forEach(e=>{const[iText,source]=e.dataset.endSource.split(':'),i=+iText;e.onpointerdown=()=>activateEndSource(i,source,e);e.onfocus=()=>activateEndSource(i,source,e);e.oninput=()=>{const s=state.steps[i],d=drive(s.drive_id),v=Number(e.value);if(!d||!Number.isFinite(v))return;s.end.source=source;s.end.input_value=v;syncEndForStep(s,i);refreshCurrentStepValues()};e.onchange=()=>{const s=state.steps[i],d=drive(s.drive_id);if(!d)return;syncEndForStep(s,i);const unclamped=Number(s.end.value),clamped=clampDriveValue(d,unclamped);if(Math.abs(clamped-unclamped)>1e-9){s.end.value=clamped;const metrics=endMetrics(s,d,i);s.end.input_value=metrics[source];toast(`目标位置已限制在 ${formatNumber(d.reverse_limit)} ~ ${formatNumber(d.forward_limit)}`,'error')}refreshCurrentStepValues()}});$$('[data-del-step]').forEach(e=>e.onclick=()=>{state.steps.splice(+e.dataset.delStep,1);renderSteps()});bindStepDragging()}
function bindStepDragging(){$$('[data-drag-step]').forEach(handle=>{handle.addEventListener('dragstart',event=>{const index=+handle.dataset.dragStep;state.dragStepIndex=index;handle.closest('.step-card')?.classList.add('is-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(index));try{event.dataTransfer.setDragImage(handle.closest('.step-card'),18,18)}catch{}});handle.addEventListener('dragend',()=>{$$('.step-card').forEach(card=>card.classList.remove('is-dragging','drag-over-before','drag-over-after'));state.dragStepIndex=null});handle.addEventListener('keydown',event=>{if(event.key==='ArrowUp'){event.preventDefault();move(+handle.dataset.dragStep,-1)}else if(event.key==='ArrowDown'){event.preventDefault();move(+handle.dataset.dragStep,1)}})});$$('[data-step-card]').forEach(card=>{card.addEventListener('dragover',event=>{if(state.dragStepIndex===null)return;event.preventDefault();event.dataTransfer.dropEffect='move';const rect=card.getBoundingClientRect(),after=event.clientY>rect.top+rect.height/2;card.classList.toggle('drag-over-before',!after);card.classList.toggle('drag-over-after',after)});card.addEventListener('dragleave',()=>card.classList.remove('drag-over-before','drag-over-after'));card.addEventListener('drop',event=>{if(state.dragStepIndex===null)return;event.preventDefault();const target=+card.dataset.stepCard,rect=card.getBoundingClientRect(),after=event.clientY>rect.top+rect.height/2;moveTo(state.dragStepIndex,target+(after?1:0))})})}
function move(i,d){const j=i+d;if(j<0||j>=state.steps.length)return;[state.steps[i],state.steps[j]]=[state.steps[j],state.steps[i]];renderSteps();requestAnimationFrame(()=>document.querySelector(`[data-drag-step="${j}"]`)?.focus())}
function moveTo(from,insertion){if(from<0||from>=state.steps.length)return;let to=Math.max(0,Math.min(state.steps.length,insertion));const[item]=state.steps.splice(from,1);if(from<to)to-=1;state.steps.splice(to,0,item);state.dragStepIndex=null;renderSteps()}
async function saveModel(){state.model=(await api(`/api/models/${state.model.id}`,{method:'PUT',body:JSON.stringify({model:state.model})})).model;renderAll()}
async function saveStepsAsPreset(){if(!state.model||!state.steps.length){toast('请先添加控制步骤','error');return}try{validSteps()}catch(error){toast(error.message,'error');return}const suggested=`控制逻辑 ${state.model.presets.length+1}`,raw=prompt('保存步骤名称',suggested);if(raw===null)return;const name=raw.trim();if(!name){toast('保存名称不能为空','error');return}const existing=state.model.presets.find(p=>p.name===name);const preset={id:existing?.id||uid('preset'),name,steps:state.steps.map((step,index)=>serializeStep(step,index))};if(existing){if(!confirm(`“${name}”已存在，是否覆盖？`))return;Object.assign(existing,preset)}else state.model.presets.push(preset);try{await saveModel();toast(`已保存“${name}”`,'success')}catch(error){toast(error.message,'error')}}
function showMemoryEditor(id){const item=memory(id);if(!item||!state.model)return;const root=$('#modalRoot'),drives=state.model.drives||[];root.innerHTML=`<div class="modal-backdrop memory-editor-backdrop" data-memory-backdrop><div class="modal memory-editor-modal" role="dialog" aria-modal="true" aria-labelledby="memoryEditorTitle"><h3 id="memoryEditorTitle">编辑记忆位置</h3><div class="modal-content memory-editor-content"><label class="memory-editor-name">名称<input id="memoryEditorName" maxlength="80" value="${esc(item.name)}"></label><div class="memory-editor-hint">记忆数据默认保持折叠。这里按驱动编辑 0–100% 百分比，保存时自动换算为对应的实际位置。</div><div class="memory-editor-list">${drives.map(d=>{const current=Number(item.positions?.[d.id]),pct=Number.isFinite(current)?percent(d,current):0,pos=positionFromPercent(d,pct);return `<div class="memory-editor-drive"><div class="memory-editor-drive-name"><strong>${esc(d.name)}</strong><small>${esc(activityPart(d.activity_part_id)?.name||'未分组')}</small></div><label class="memory-percent-field"><span>百分比</span><div><input data-memory-percent="${d.id}" type="number" min="0" max="100" step="0.1" value="${formatNumber(pct,1)}"><b>%</b></div></label><div class="memory-position-preview"><span>实际位置</span><strong data-memory-position="${d.id}">${formatNumber(pos)}</strong></div></div>`}).join('')||'<div class="empty-state compact-empty">当前模型没有可编辑驱动</div>'}</div></div><div class="modal-actions"><button class="ghost" data-memory-cancel>取消</button><button class="primary" data-memory-save>保存</button></div></div></div>`;const close=()=>{document.removeEventListener('keydown',onKeydown);root.innerHTML=''},onKeydown=event=>{if(event.key==='Escape')close()};document.addEventListener('keydown',onKeydown);root.querySelector('[data-memory-cancel]').onclick=close;root.querySelector('[data-memory-backdrop]').onclick=event=>{if(event.target===event.currentTarget)close()};$$('[data-memory-percent]').forEach(input=>{input.oninput=()=>{const d=drive(input.dataset.memoryPercent),v=Number(input.value),preview=root.querySelector(`[data-memory-position="${input.dataset.memoryPercent}"]`);if(!d||!preview)return;preview.textContent=Number.isFinite(v)&&v>=0&&v<=100?formatNumber(positionFromPercent(d,v)):'—'}});root.querySelector('[data-memory-save]').onclick=async()=>{const name=root.querySelector('#memoryEditorName').value.trim();if(!name){toast('记忆位置名称不能为空','error');return}const positions={};for(const input of root.querySelectorAll('[data-memory-percent]')){const d=drive(input.dataset.memoryPercent),pct=Number(input.value);if(!d||!Number.isFinite(pct)||pct<0||pct>100){toast(`${d?.name||'驱动'} 的百分比必须在 0–100% 之间`,'error');input.focus();return}positions[d.id]=positionFromPercent(d,pct)}const previous={name:item.name,positions:clone(item.positions||{})};item.name=name;item.positions=positions;const saveButton=root.querySelector('[data-memory-save]');saveButton.disabled=true;try{await saveModel();close();toast(`“${name}”已保存`,'success')}catch(error){item.name=previous.name;item.positions=previous.positions;saveButton.disabled=false;toast(error.message,'error')}};requestAnimationFrame(()=>root.querySelector('#memoryEditorName')?.focus())}
async function createMemory(){const name=prompt('记忆位置名称',`位置${state.model.memories.length+1}`);if(!name?.trim())return;const positions={};for(const d of state.model.drives){const[p0]=calibration(d);const raw=prompt(`${d.name} 的位置（${d.reverse_limit} ~ ${d.forward_limit}）`,String(p0));if(raw===null)return;const v=Number(raw);if(!Number.isFinite(v)||v<d.reverse_limit||v>d.forward_limit){toast(`${d.name} 的位置超出范围`,'error');return}positions[d.id]=v}state.model.memories.push({id:uid('memory'),name:name.trim(),positions});try{await saveModel();toast('记忆位置已创建')}catch(e){toast(e.message,'error')}}
async function renameMemory(id){const item=memory(id);if(!item)return;const name=prompt('修改记忆位置名称',item.name);if(name===null)return;const next=name.trim();if(!next){toast('记忆位置名称不能为空','error');return}if(next===item.name)return;item.name=next;try{await saveModel();toast('记忆位置名称已修改')}catch(e){toast(e.message,'error')}}
async function jumpToMemory(id,button){const item=memory(id);if(!item||!state.model||state.poseBusy)return;const original=button?.textContent||'跳转',snapshot=pushUndoSnapshot(),actionToken=beginPoseAction();try{if(button)button.innerHTML='<i class="spinner dark"></i> 跳转中';const modelId=state.model.id,token=++state.loadToken,applied=await loadAnimation({modelId,autoplay:true,camera:state.camera,token,memoryJumpId:id,initialPositions:snapshot?.positions||{...state.currentPositions}});if(!applied){discardUndoSnapshot(snapshot);return}toast(`正在从当前动画位置跳转到“${item.name}”`)}catch(e){discardUndoSnapshot(snapshot);toast(e.message,'error')}finally{endPoseAction(actionToken);if(button?.isConnected)button.textContent=original}}
async function deleteMemory(id){if(!confirm(`删除记忆位置“${memory(id)?.name}”？`))return;if(state.steps.some(s=>s.start.memory_id===id||s.end.memory_id===id)){toast('该记忆位置仍被控制步骤使用','error');return}state.model.memories=state.model.memories.filter(x=>x.id!==id);try{await saveModel();toast('记忆位置已删除')}catch(e){toast(e.message,'error')}}
$$('[data-upper]').forEach(b=>b.onclick=()=>{state.upper=b.dataset.upper;$$('[data-upper]').forEach(x=>x.classList.toggle('active',x===b));renderUpper();updateActionButtons()});$('#addMemory').onclick=createMemory;$('#modelSelect').onchange=e=>selectModel(e.target.value).catch(x=>toast(x.message,'error'));$('#renderQualityToggle').onchange=e=>{state.renderQuality=e.target.checked?'perfect':'preview';applyRenderQualityUi();toast(`已切换为${e.target.checked?'高质量渲染':'快速渲染'}，点击“保存设置”可持久化`)};$('#saveUserSettings').onclick=saveClientSettings;$('#addStep').onclick=()=>{state.steps.push(defaultStep());renderSteps()};$('#clearSteps').onclick=()=>{state.steps=[];renderSteps()};$('#saveSteps').onclick=saveStepsAsPreset;$('#undoPosition').onclick=undoLastPosition;
function validSteps(){for(let i=0;i<state.steps.length;i++){const s=state.steps[i],d=drive(s.drive_id);if(!d)throw new Error(`第 ${i+1} 步未选择动作`);if(s.start?.mode==='value'&&!Number.isFinite(Number(s.start.value)))throw new Error(`第 ${i+1} 步起始位置无效`);syncEndForStep(s,i);const end=Number(s.end?.value);if(!Number.isFinite(end))throw new Error(`第 ${i+1} 步结束位置无效`);if(end<Number(d.reverse_limit)-1e-9||end>Number(d.forward_limit)+1e-9)throw new Error(`第 ${i+1} 步结束位置超出 ${d.reverse_limit} ~ ${d.forward_limit}`)}return true}
$('#simulate').onclick=async()=>{const btn=$('#simulate');if(!state.model||state.poseBusy)return;let snapshot=null,actionToken=0;try{if(state.manualMode)validSteps();else if(!state.externalTable)throw new Error('请先导入外部 CSV 表格');snapshot=pushUndoSnapshot();actionToken=beginPoseAction();btn.innerHTML='<i class="spinner"></i> 正在生成动画';const modelId=state.model.id,token=++state.loadToken,steps=state.manualMode?state.steps:[],tableSequence=state.manualMode?null:state.externalTable.sequence,applied=await loadAnimation({modelId,steps,tableSequence,autoplay:state.manualMode?steps.length>0:true,camera:state.camera,token,initialPositions:snapshot?.positions||{...state.currentPositions}});if(!applied)discardUndoSnapshot(snapshot)}catch(e){discardUndoSnapshot(snapshot);toast(e.message,'error')}finally{btn.textContent='▶ 发送并仿真';if(actionToken)endPoseAction(actionToken)}};
$('#clientEditorBack')?.addEventListener('click',closeUserTimeSeriesEditor);
$('#clientEditorSeriesTabs')?.addEventListener('click',event=>{const button=event.target.closest('[data-user-editor-series]');if(!button)return;state.timeSeriesSelection.set(state.userTimeSeries.modelId,button.dataset.userEditorSeries);renderUserTimeSeriesEditor();renderSceneControlBoard()});
$('#clientEditorGantt')?.addEventListener('dblclick',event=>{const block=event.target.closest('[data-user-ts-segment]');if(block)openUserSegmentEditor(block.dataset.userTsDrive,block.dataset.userTsSegment).catch(error=>toast(error.message,'error'))});
