$('#clientEditorScaleY')?.addEventListener('input',event=>{state.userTimeSeries.scaleY=Number(event.target.value)||100;$('#clientEditorScaleYValue').textContent=`${state.userTimeSeries.scaleY}%`;renderUserTimeSeriesEditor()});
$('#clientEditorCursor')?.addEventListener('change',event=>{state.userTimeSeries.cursorVisible=!!event.target.checked;renderUserTimeSeriesEditor()});
$('#clientEditorSortDesc')?.addEventListener('change',event=>{state.userTimeSeries.sortDesc=!!event.target.checked;renderUserTimeSeriesEditor()});
window.addEventListener('message',e=>{if(e.source!==$('#animationFrame').contentWindow)return;const msg=e.data||{};if(msg.type==='vz-camera-state'&&msg.camera&&msg.model_id){if(state.model?.id===msg.model_id)state.camera=msg.camera;return}if(msg.type==='vz-drive-positions'&&msg.model_id===state.model?.id&&msg.positions&&typeof msg.positions==='object'){const next={...state.currentPositions};for(const[dId,value]of Object.entries(msg.positions)){const n=Number(value);if(Number.isFinite(n))next[dId]=n}state.currentPositions=next;refreshCurrentStepValues()}});
bindSceneBoard();bindGraphCanvas();loadModels().then(()=>refreshSceneTimeSeries()).catch(e=>toast(e.message,'error'));setInterval(()=>{if(document.visibilityState==='visible')void refreshSceneTimeSeries()},5000);
